using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.RegularExpressions;
namespace LocalChat;
static class WebReader {
 public static bool Public(IPAddress address){if(address.IsIPv4MappedToIPv6)address=address.MapToIPv4();if(IPAddress.IsLoopback(address))return false;var b=address.GetAddressBytes();if(b.Length==16)return (b[0]&0xe0)==0x20;return !(b[0] is 0 or 10 or 127||b[0]>=224||b[0]==169&&b[1]==254||b[0]==172&&b[1]>=16&&b[1]<=31||b[0]==192&&(b[1]==168||b[1]==0)||b[0]==100&&b[1]>=64&&b[1]<=127||b[0]==198&&(b[1]==18||b[1]==19));}
 public static Uri Parse(string text){if(!Uri.TryCreate(text.Trim(),UriKind.Absolute,out var uri)||uri.Scheme!="https"||!uri.IsDefaultPort||uri.UserInfo!=""||uri.HostNameType is not (UriHostNameType.Dns or UriHostNameType.IPv4 or UriHostNameType.IPv6))throw new Exception("Разрешены только публичные HTTPS-страницы без логина и нестандартного порта.");return uri;}
 public static async Task<(string title,string text)> Read(string url,CancellationToken token){var uri=Parse(url);using var handler=new SocketsHttpHandler{AllowAutoRedirect=false,UseProxy=false,UseCookies=false,AutomaticDecompression=DecompressionMethods.All};
  handler.ConnectCallback=async(context,ct)=>{var addresses=await Dns.GetHostAddressesAsync(context.DnsEndPoint.Host,ct);if(addresses.Length==0||addresses.Any(a=>!Public(a)))throw new Exception("Локальные и служебные сетевые адреса не разрешены.");var socket=new Socket(SocketType.Stream,ProtocolType.Tcp);try{await socket.ConnectAsync(addresses,context.DnsEndPoint.Port,ct);return new NetworkStream(socket,true);}catch{socket.Dispose();throw;}};
  using var client=new HttpClient(handler){Timeout=TimeSpan.FromSeconds(30)};client.DefaultRequestHeaders.UserAgent.ParseAdd("NORA/2.0");using var response=await client.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,token);if((int)response.StatusCode>=300&&(int)response.StatusCode<400)throw new Exception("Сайт перенаправляет на другой адрес. Скопируй конечную HTTPS-ссылку из своего браузера.");response.EnsureSuccessStatusCode();string type=response.Content.Headers.ContentType?.MediaType??"";if(!new[]{"text/html","text/plain","application/xhtml+xml"}.Contains(type))throw new Exception("По ссылке не HTML/текст. Скачай документ в браузере и прикрепи как файл.");
  using var stream=await response.Content.ReadAsStreamAsync(token);using var bytes=new MemoryStream();byte[] buf=new byte[8192];int n;while((n=await stream.ReadAsync(buf,token))>0){if(bytes.Length+n>2*1024*1024)throw new Exception("Страница больше 2 МБ.");await bytes.WriteAsync(buf.AsMemory(0,n),token);}string html=Encoding.UTF8.GetString(bytes.ToArray());string title=WebUtility.HtmlDecode(Regex.Match(html,"<title[^>]*>(.*?)</title>",RegexOptions.IgnoreCase|RegexOptions.Singleline).Groups[1].Value);if(title.Length==0)title=uri.Host;
  var doc=new HtmlAgilityPack.HtmlDocument();doc.LoadHtml(html);foreach(var node in doc.DocumentNode.SelectNodes("//script|//style|//nav|//footer|//noscript|//svg")??Enumerable.Empty<HtmlAgilityPack.HtmlNode>())node.Remove();string text=WebUtility.HtmlDecode(doc.DocumentNode.InnerText);text=Regex.Replace(text,@"\s+"," ").Trim();if(text.Length==0)throw new Exception("На странице нет текста. JavaScript, вход в аккаунт и видео этим инструментом не поддерживаются.");return(title,"URL: "+uri+"\n"+text[..Math.Min(text.Length,60000)]);
 }
}
